# Define indicator calculation functions
def calculate_rsi(close, period):
    delta = close.diff(1)
    up, down = delta.copy(), delta.copy()
    up[up < 0] = 0
    down[down > 0] = 0
    roll_up = up.ewm(com=period - 1, adjust=False).mean()
    roll_down = down.ewm(com=period - 1, adjust=False).mean().abs()
    RS = roll_up / roll_down
    RSI = 100.0 - (100.0 / (1.0 + RS))
    return RSI

def calculate_adx(high, low, close, period):
    plus_dm = high.diff(1)
    minus_dm = low.diff(1)
    plus_dm[plus_dm < 0] = 0
    minus_dm[minus_dm > 0] = 0
    tr = ((high - low) + (high - close.shift(1)) + (low - close.shift(1))) / 3
    tr = tr.abs()
    plus_di = (plus_dm / tr) * 100
    minus_di = (minus_dm / tr) * 100
    dx = (plus_di - minus_di).abs() / ((plus_di + minus_di))
    adx = dx.ewm(com=period - 1, adjust=False).mean()
    return adx

